public class ExpenseReportTests
{
    private static ExpenseReport CreateReport(Guid orgId, Guid empId)
    {
        return new ExpenseReport(employeeId: empId, organizationId: orgId);
    }

    [Fact]
    public void AddLineItem_WhenDraft_ShouldAddItem()
    {
        var report = CreateReport(Guid.NewGuid(), Guid.NewGuid());
        var item = new LineItem(Category: LineItemCategory.Meals, Amount: new Money(25m, "USD"), Date: DateOnly.FromDateTime(DateTime.UtcNow));

        report.AddLineItem(item);

        report.LineItems.Should().ContainSingle().Which.Category.Should().Be(LineItemCategory.Meals);
    }

    [Theory]
    [InlineData(ReportStatus.Approved)]
    [InlineData(ReportStatus.Submitted)]
    [InlineData(ReportStatus.Rejected)]
    public void AddLineItem_WhenNotDraft_ShouldThrow(ReportStatus status)
    {
        var report = CreateReport(Guid.NewGuid(), Guid.NewGuid());
        report.Submit(new StubPolicyEngine()); // transitions to Submitted
        if (status == ReportStatus.Approved) report.Approve(Guid.NewGuid());
        if (status == ReportStatus.Rejected) report.Reject(Guid.NewGuid(), "reason");

        var item = new LineItem(LineItemCategory.Meals, new Money(10m, "USD"), DateOnly.FromDateTime(DateTime.UtcNow));
        report.Invoking(r => r.AddLineItem(item))
            .Should().Throw<DomainException>()
            .WithMessage("*modify a submitted report*");
    }

    [Fact]
    public void Submit_WithNoLineItems_ShouldThrow()
    {
        var report = CreateReport(Guid.NewGuid(), Guid.NewGuid());
        report.Invoking(r => r.Submit(new StubPolicyEngine()))
            .Should().Throw<DomainException>()
            .WithMessage("*at least one line item*");
    }

    [Fact]
    public void Approve_WhenSubmitted_ShouldEmitDomainEvent()
    {
        var report = CreateReport(Guid.NewGuid(), Guid.NewGuid());
        report.AddLineItem(new LineItem(LineItemCategory.Travel, new Money(100m, "USD"), DateOnly.FromDateTime(DateTime.UtcNow)));
        report.Submit(new StubPolicyEngine());
        var approver = Guid.NewGuid();

        report.Approve(approver);

        report.Status.Should().Be(ReportStatus.Approved);
        report.GetUncommittedEvents().Should().ContainSingle().
            Which.Should().BeOfType<ExpenseReportApproved>();
    }
}

public class SubmitExpenseReportHandlerTests
{
    [Fact]
    public async Task Handle_WithValidRequest_ShouldReturnReportId()
    {
        // Arrange
        var reports = new Mock<IExpenseReportRepository>();
        var policy = new Mock<IPolicyEngine>();
        var uow = new Mock<IUnitOfWork>();
        var orgId = Guid.NewGuid();
        var empId = Guid.NewGuid();
        var savedReport = new ExpenseReport(empId, orgId);
        reports.Setup(r => r.AddAsync(It.IsAny<ExpenseReport>(), It.IsAny<CancellationToken>()))
            .Callback<ExpenseReport, CancellationToken>((r, _) => savedReport = r)
            .Returns(Task.CompletedTask);

        var handler = new SubmitExpenseReportHandler(reports.Object, policy.Object, uow.Object, NullLogger<SubmitExpenseReportHandler>.Instance);
        var command = new SubmitExpenseReportCommand(
            OrganizationId: orgId,
            EmployeeId: empId,
            LineItems: [
                new CreateLineItemDto(LineItemCategory.Meals, new Money(25m, "USD"), DateOnly.FromDateTime(DateTime.UtcNow), null, null)
            ]);

        // Act
        var result = await handler.Handle(command, CancellationToken.None);

        // Assert
        result.IsSuccess.Should().BeTrue();
        result.Value.Should().NotBeEmpty();
        reports.Verify(r => r.AddAsync(It.IsAny<ExpenseReport>(), It.IsAny<CancellationToken>()), Times.Once);
        uow.Verify(u => u.SaveChangesAsync(It.IsAny<CancellationToken>()), Times.Once);
    }
}

public class IntegrationTestFixture : IAsyncLifetime
{
    private readonly WebApplicationFactory<Program> _factory;
    private readonly Respawner _checkpoint;
    private readonly string _connectionString;

    public HttpClient Client { get; private set; } = null!;

    public IntegrationTestFixture()
    {
        _connectionString = Environment.GetEnvironmentVariable("TEST_CONNECTION_STRING")
            ?? throw new InvalidOperationException("TEST_CONNECTION_STRING is required.");
        _factory = new WebApplicationFactory<Program>()
            .WithWebHostBuilder(b =>
            {
                b.ConfigureServices(services =>
                {
                    services.RemoveAll<DbContextOptions<ExpenseDbContext>>();
                    services.AddDbContext<ExpenseDbContext>(opt =>
                        opt.UseSqlServer(_connectionString));
                });
            });
    }

    public async Task InitializeAsync()
    {
        Client = _factory.CreateClient();
        _checkpoint = await Respawner.CreateAsync(_connectionString, new RespawnerOptions
        {
            TablesToIgnore = ["__EFMigrationsHistory"],
            DbAdapter = DbAdapter.SqlServer
        });
        await ResetDatabaseAsync();
    }

    public async Task ResetDatabaseAsync()
    {
        await using var conn = new SqlConnection(_connectionString);
        await conn.OpenAsync();
        await _checkpoint.ResetAsync(conn);
    }

    public async Task DisposeAsync() => await _factory.DisposeAsync();
}

