public class SubmitExpenseReportIntegrationTests : IClassFixture<IntegrationTestFixture>
{
    private readonly IntegrationTestFixture _fixture;

    public SubmitExpenseReportIntegrationTests(IntegrationTestFixture fixture)
    {
        _fixture = fixture;
    }

    [Fact]
    public async Task Submit_WithValidPayload_Returns201WithReportId()
    {
        // Arrange: seed org and user, get JWT
        var org = await _fixture.SeedOrganizationAsync("acme");
        var token = await _fixture.GetJwtForUserAsync(org.Id, role: "Employee");
        _fixture.Client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", token);

        var payload = new
        {
            organizationId = org.Id.ToString(),
            lineItems = new[]
            {
                new { category = "Meals", amount = new { amount = 25.00m, currency = "USD" }, date = DateOnly.FromDateTime(DateTime.UtcNow).ToString() }
            }
        };

        // Act
        var response = await _fixture.Client.PostAsJsonAsync("/api/expense-reports", payload);

        // Assert
        response.StatusCode.Should().Be(HttpStatusCode.Created);
        var body = await response.Content.ReadFromJsonAsync<SubmitResponse>();
        body.Should().NotBeNull();
        body!.Id.Should().NotBeEmpty();
    }
}

